CREATE OR REPLACE FUNCTION public.revise_occurrence_classification(p_occurrence_id uuid,p_impact public.occ_level,p_urgency public.occ_level,p_category_id uuid,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.occurrences; a public.accounts; t public.sla_targets; basis timestamptz; due timestamptz; BEGIN IF NOT public.has_occurrence_access(p_occurrence_id) OR coalesce(public.current_app_role() NOT IN ('kam','ops_manager'),true) THEN RAISE EXCEPTION 'Somente KAM ou gestor pode revisar a classificação'; END IF; SELECT * INTO STRICT o FROM public.occurrences WHERE id=p_occurrence_id FOR UPDATE; IF o.status NOT IN ('registered','in_analysis','in_treatment','awaiting_customer','reopened') OR length(trim(coalesce(p_reason,'')))=0 THEN RAISE EXCEPTION 'Informe a justificativa em uma ocorrência ativa'; END IF; IF NOT EXISTS(SELECT 1 FROM public.categories WHERE id=p_category_id AND active AND parent_id IS NULL) THEN RAISE EXCEPTION 'Categoria inválida'; END IF; SELECT * INTO STRICT a FROM public.accounts WHERE id=o.account_id; SELECT * INTO STRICT t FROM public.sla_targets WHERE policy_id=a.sla_policy_id AND severity=public.calculate_severity(p_impact,p_urgency); basis:=CASE WHEN o.reopen_count>0 THEN o.resolution_started_at ELSE o.created_at END; due:=public.add_business_minutes(a.calendar_id,basis,t.resolution_minutes+o.paused_business_minutes); UPDATE public.occurrences SET impact=p_impact,urgency=p_urgency,category_id=p_category_id,subcategory_id=CASE WHEN category_id=p_category_id THEN subcategory_id ELSE NULL END,classification_confirmed_at=now(),classification_confirmed_by=auth.uid(),first_response_due_at=CASE WHEN o.reopen_count>0 THEN o.first_response_due_at ELSE public.add_business_minutes(a.calendar_id,o.created_at,t.first_response_minutes) END,resolution_due_at=due,first_response_breached=first_response_breached OR (o.reopen_count=0 AND coalesce(o.first_response_at,now())>public.add_business_minutes(a.calendar_id,o.created_at,t.first_response_minutes)),resolution_breached=resolution_breached OR coalesce(o.paused_since,now())>due WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body,metadata) VALUES(o.id,'system','system',auth.uid(),trim(p_reason),jsonb_build_object('action','classification_revision','old_severity',o.severity,'new_severity',t.severity,'old_category_id',o.category_id,'new_category_id',p_category_id,'resolution_basis',basis,'cycle',o.reopen_count+1)); END $$;
DO $$ DECLARE definition text; BEGIN definition:=pg_get_functiondef('public.available_transitions(uuid)'::regprocedure); definition:=replace(definition,'AND o.reopen_count=0 AND o.status IN (''registered'',''in_analysis'',''in_treatment'',''awaiting_customer'')','AND o.status IN (''registered'',''in_analysis'',''in_treatment'',''awaiting_customer'',''reopened'')'); EXECUTE definition; END $$;
COMMENT ON FUNCTION public.revise_occurrence_classification(uuid,public.occ_level,public.occ_level,uuid,text) IS 'Severity changes recalculate solution from active resolution cycle start after reopening; first response deadline is unchanged in reopened cycles.';